window.CODE = Object.assign(window.CODE || {}, {"ch12/first_chain.py":"\"\"\"Your first LangChain chain: prompt | model | parser.\n\nEvery piece is a Runnable, so they all share the same methods:\ninvoke (one input), batch (many inputs), stream (piece by piece) and ainvoke (async).\n\nRun:  python first_chain.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langchain_core.output_parsers import StrOutputParser  # noqa: E402\nfrom langchain_core.prompts import ChatPromptTemplate  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\n# 1. A prompt template: fixed instructions with {placeholders} filled in at run time.\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"You are the City Clinic helpdesk. Reply in {language}, in at most two sentences. \"\n               \"Use only these facts: {facts}\"),\n    (\"user\", \"{question}\"),\n])\n\n# 2. The model. To switch provider, change PROVIDER in .env, or write:\n#    init_chat_model(\"openai:gpt-4.1-mini\")   or   init_chat_model(\"anthropic:claude-haiku-5-5\")\nmodel = get_model()\n\n# 3. A parser turns the model's message object into a plain string.\nchain = prompt | model | StrOutputParser()\n\nFACTS = \"OPD runs Monday to Saturday, 9 am-1 pm and 4-7 pm. Closed on Sundays.\"\n\nif __name__ == \"__main__\":\n    # invoke: one input dict -> one output\n    print(\"invoke:\", chain.invoke({\"language\": \"English\", \"facts\": FACTS,\n                                   \"question\": \"Is OPD open on Sunday?\"}))\n\n    # batch: several inputs, run in parallel threads\n    answers = chain.batch([\n        {\"language\": \"Hindi\", \"facts\": FACTS, \"question\": \"OPD kab khulta hai?\"},\n        {\"language\": \"English\", \"facts\": FACTS, \"question\": \"Can I come at 2 pm?\"},\n    ], config={\"max_concurrency\": 2})\n    for a in answers:\n        print(\"batch: \", a)\n\n    # stream: print words as they arrive\n    print(\"stream:\", end=\" \")\n    for piece in chain.stream({\"language\": \"English\", \"facts\": FACTS, \"question\": \"Evening timings?\"}):\n        print(piece, end=\"\", flush=True)\n    print()\n\n    # What the model actually received: the filled-in prompt\n    print(\"\\nPrompt sent:\", prompt.invoke({\"language\": \"English\", \"facts\": FACTS,\n                                          \"question\": \"Is OPD open on Sunday?\"}).to_messages())\n","ch12/production_chain.py":"\"\"\"Making a chain production-ready: tracing callbacks, retries, fallbacks, concurrency limits and caching.\n\nRun:  python production_chain.py\n\"\"\"\nimport sys\nimport time\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langchain_core.callbacks import BaseCallbackHandler  # noqa: E402\nfrom langchain_core.caches import InMemoryCache  # noqa: E402\nfrom langchain_core.globals import set_llm_cache  # noqa: E402\nfrom langchain_core.output_parsers import StrOutputParser  # noqa: E402\nfrom langchain_core.prompts import ChatPromptTemplate  # noqa: E402\nfrom lc_models import PROVIDER, get_model  # noqa: E402\n\n\nclass CostTracker(BaseCallbackHandler):\n    \"\"\"Callbacks fire on every model call. Use them for logs, token counts, latency and alerts.\n    (LangSmith and Langfuse plug in the same way; see Chapter 31.)\"\"\"\n\n    def __init__(self):\n        self.calls, self.input_tokens, self.output_tokens, self._t = 0, 0, 0, {}\n\n    def on_chat_model_start(self, serialized, messages, *, run_id, **kw):\n        self._t[run_id] = time.perf_counter()\n\n    def on_llm_end(self, response, *, run_id, **kw):\n        self.calls += 1\n        for gen in response.generations[0]:\n            usage = getattr(gen.message, \"usage_metadata\", None) or {}\n            self.input_tokens += usage.get(\"input_tokens\", 0)\n            self.output_tokens += usage.get(\"output_tokens\", 0)\n        ms = (time.perf_counter() - self._t.pop(run_id, time.perf_counter())) * 1000\n        print(f\"  [trace] answer {self.calls}: {ms:.0f} ms\")\n\n    def on_llm_error(self, error, *, run_id, **kw):\n        print(f\"  [trace] model error: {type(error).__name__}: {error}\")\n\n\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"You are the City Clinic helpdesk. One short sentence. OPD: Mon-Sat 9-1 and 4-7.\"),\n    (\"user\", \"{question}\")])\n\nprimary = get_model().with_retry(stop_after_attempt=3)       # retry transient errors with backoff\nbackup = get_model(provider=\"anthropic\" if PROVIDER == \"openai\" else \"openai\")   # needs both API keys\nmodel = primary.with_fallbacks([backup])                     # if the provider is down, use the other one\n\nchain = prompt | model | StrOutputParser()\n\nif __name__ == \"__main__\":\n    set_llm_cache(InMemoryCache())        # identical prompts are answered from cache (use Redis/SQLite in production)\n    tracker = CostTracker()\n    config = {\"callbacks\": [tracker], \"max_concurrency\": 4,   # max_concurrency limits parallel calls in .batch()\n              \"tags\": [\"helpdesk\"], \"run_name\": \"opd-faq\"}\n\n    questions = [\"Is OPD open Saturday?\", \"Is OPD open Sunday?\", \"Is OPD open Saturday?\"]\n    for q in questions:\n        print(f\"{q} -> {chain.invoke({'question': q}, config=config)}\")\n    # Callbacks fire for cache hits too, so the tracker sees 3 answers, but only 2 reached the API:\n    # the repeated question came from the cache, with no network call and no cost.\n    print(f\"\\nAnswers traced: {tracker.calls}; tokens reported: {tracker.input_tokens} in, {tracker.output_tokens} out\")\n","ch12/rag_chain.py":"\"\"\"Chapter 7's RAG pipeline, rebuilt with LangChain parts, plus chat history.\n\nloader -> splitter -> vector store -> retriever -> prompt (with history) -> model -> answer with sources\n\nRun:  python rag_chain.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nfrom langchain_core.documents import Document  # noqa: E402\nfrom langchain_core.messages import AIMessage, HumanMessage  # noqa: E402\nfrom langchain_core.output_parsers import StrOutputParser  # noqa: E402\nfrom langchain_core.prompts import ChatPromptTemplate, MessagesPlaceholder  # noqa: E402\nfrom langchain_core.runnables import RunnablePassthrough  # noqa: E402\nfrom langchain_core.vectorstores import InMemoryVectorStore  # noqa: E402\nfrom langchain_text_splitters import MarkdownHeaderTextSplitter  # noqa: E402\nfrom lc_models import get_embeddings, get_model  # noqa: E402\n\nDOCS = HERE.parent / \"ch07\" / \"docs\"          # the same four clinic policy files as Chapter 7\n\n\ndef load_and_split() -> list[Document]:\n    \"\"\"Load each Markdown file and split it at headings, so each chunk is one topic.\n    (For PDFs use langchain_community.document_loaders.PyPDFLoader; for folders, DirectoryLoader.)\"\"\"\n    splitter = MarkdownHeaderTextSplitter([(\"#\", \"doc\"), (\"##\", \"section\")])\n    chunks = []\n    for path in sorted(DOCS.glob(\"*.md\")):\n        for c in splitter.split_text(path.read_text(encoding=\"utf-8\")):\n            c.metadata[\"source\"] = f\"{path.name} > {c.metadata.get('section', 'intro')}\"\n            chunks.append(c)\n    return chunks\n\n\nstore = InMemoryVectorStore(get_embeddings())   # swap for Chroma, FAISS, pgvector... same interface\nstore.add_documents(load_and_split())\nretriever = store.as_retriever(search_kwargs={\"k\": 3})\n\n\ndef format_docs(docs: list[Document]) -> str:\n    return \"\\n\\n\".join(f\"[{i}] ({d.metadata['source']})\\n{d.page_content}\" for i, d in enumerate(docs, 1))\n\n\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"You are the City Clinic helpdesk. Answer ONLY from the numbered sources and cite them like [1]. \"\n               \"If the sources do not contain the answer, say you don't know and suggest the front desk \"\n               \"(1800-000-000).\\n\\nSources:\\n{context}\"),\n    MessagesPlaceholder(\"history\"),                # earlier turns of this conversation\n    (\"user\", \"{question}\"),\n])\n\nrag_chain = (\n    RunnablePassthrough.assign(context=lambda x: format_docs(retriever.invoke(x[\"question\"])))\n    | prompt | get_model() | StrOutputParser()\n)\n\nif __name__ == \"__main__\":\n    history = []\n    for q in [\"What are the OPD timings?\", \"And is the follow-up visit free?\"]:\n        answer = rag_chain.invoke({\"question\": q, \"history\": history})\n        print(f\"Q: {q}\\nA: {answer}\\n\")\n        history += [HumanMessage(q), AIMessage(answer)]     # keep the conversation for the next turn\n\n    print(\"Retrieved for the first question:\")\n    for d in retriever.invoke(\"What are the OPD timings?\"):\n        print(\"  -\", d.metadata[\"source\"])\n","ch12/serve_chain.py":"\"\"\"Serve a chain as a web API with FastAPI (Chapter 5), including a streaming endpoint.\n\nLangServe used to do this automatically; it is no longer recommended for new projects,\nand a few lines of FastAPI give you full control.\n\nRun:  uvicorn serve_chain:app --reload      then open http://127.0.0.1:8000/docs\n\"\"\"\nfrom fastapi import FastAPI\nfrom fastapi.responses import StreamingResponse\nfrom first_chain import FACTS, chain\nfrom pydantic import BaseModel, Field\n\napp = FastAPI(title=\"City Clinic FAQ chain\")\n\n\nclass Question(BaseModel):\n    question: str = Field(min_length=2, max_length=500)\n    language: str = \"English\"\n\n\n@app.post(\"/ask\")\nasync def ask(q: Question) -> dict:\n    answer = await chain.ainvoke({\"question\": q.question, \"language\": q.language, \"facts\": FACTS})\n    return {\"answer\": answer}\n\n\n@app.post(\"/ask/stream\")\nasync def ask_stream(q: Question):\n    async def events():\n        async for piece in chain.astream({\"question\": q.question, \"language\": q.language, \"facts\": FACTS}):\n            yield f\"data: {piece}\\n\\n\"            # Server-Sent Events, as in Chapter 5\n        yield \"data: [DONE]\\n\\n\"\n    return StreamingResponse(events(), media_type=\"text/event-stream\")\n","ch12/structured_chain.py":"\"\"\"Structured output and composing chains: triage a patient message, then route it.\n\nwith_structured_output(PydanticModel)  -> the model must return that shape; you get a Python object\nRunnableParallel                       -> run several chains on the same input at once\nRunnableLambda                         -> wrap any Python function as a Runnable\nRunnableBranch-style routing           -> a plain function that picks the next chain\n\nRun:  python structured_chain.py\n\"\"\"\nimport sys\nfrom pathlib import Path\nfrom typing import Literal\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langchain_core.output_parsers import StrOutputParser  # noqa: E402\nfrom langchain_core.prompts import ChatPromptTemplate  # noqa: E402\nfrom langchain_core.runnables import RunnableLambda, RunnableParallel, RunnablePassthrough  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel, Field  # noqa: E402\n\n\nclass Triage(BaseModel):\n    \"\"\"How the helpdesk should handle a patient message.\"\"\"\n    intent: Literal[\"schedule\", \"billing\", \"emergency\", \"other\"]\n    department: str | None = Field(None, description=\"Hospital department if one is mentioned or implied\")\n    urgent: bool = Field(description=\"True for chest pain, breathing trouble, heavy bleeding or unconsciousness\")\n\n\nmodel = get_model()\n\ntriage_chain = (\n    ChatPromptTemplate.from_messages([\n        (\"system\", \"Classify the City Clinic patient message. Do not answer it.\"),\n        (\"user\", \"{message}\")])\n    | model.with_structured_output(Triage)        # returns a Triage object, already validated\n)\n\nreply_prompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"You are the City Clinic helpdesk. The message is about {intent}. Reply in one or two \"\n               \"short sentences. Never give medical advice.\"),\n    (\"user\", \"{message}\")])\nreply_chain = reply_prompt | model | StrOutputParser()\n\nEMERGENCY = RunnableLambda(lambda x: \"Please go to Emergency now or call 108. A nurse is being alerted.\")\n\n\ndef route(x: dict):\n    \"\"\"Pick the next step from the triage result. Hard safety rules live in code, not in the prompt.\"\"\"\n    t: Triage = x[\"triage\"]\n    if t.urgent or t.intent == \"emergency\":\n        return EMERGENCY\n    return RunnablePassthrough.assign(intent=lambda x: x[\"triage\"].intent) | reply_chain\n\n\n# The full pipeline: keep the message AND add a triage result, then route.\npipeline = RunnableParallel(message=RunnablePassthrough(), triage=triage_chain) | RunnableLambda(route)\n\nif __name__ == \"__main__\":\n    for msg in [\"Which days does the cardiologist see patients?\",\n                \"Why was I charged twice for my ECG?\",\n                \"My father has chest pain and is sweating\"]:\n        t = triage_chain.invoke({\"message\": msg})\n        print(f\"{msg}\\n  triage: {t.model_dump()}\")\n        print(f\"  reply:  {pipeline.invoke(msg)}\\n\")\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
